package net.civeira.phylax.feature.identity.consentpurpose.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.identity.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.feature.identity.consentpurpose.domain.event.ConsentPurposeEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ConsentPurposeEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ConsentPurposeEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ConsentPurpose entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
